    'meteo.caricoPrevisioni': 'Carico le previsioni…',
    'meteo.senzaRete': 'Previsioni non disponibili (serve la rete). Il resto dei dati è calcolato in locale e resta valido.',
    'meteo.nessunaPerStanotte': 'Nessuna previsione per le ore di questa notte.',
    'meteo.mediaStanotte': '({n}% di nuvole in media stanotte)',
    'meteo.nuvoleNelPlanetario': 'Le nuvole che vedi seguono la previsione meteo ({n}% di copertura). Puoi nasconderle subito e continuare a leggere la carta celeste.',
    'meteo.nascondiNuvole': 'Nascondi nuvole',
    'meteo.oraMigliore': 'Ora migliore: {ora} con {n}%',
    'meteo.previsioneDi': 'previsione di {quanto}',

    // --- La cornice dell'agenda e della griglia del mese ----------------
    'agenda.nessunEvento': 'Nessun evento da mostrare.',
    'agenda.nessunEventoNelMese': 'Nessun evento in {mese} {anno} con i filtri attivi. Prova a cambiare mese, ricerca o categoria.',
    'agenda.nessunEventoTrovato': 'Nessun evento corrisponde alla ricerca. Prova a cambiare i termini o la categoria.',
    'agenda.manuale': 'Manuale',
    'agenda.modifica': 'Modifica',
    'agenda.modificaTitolo': 'Modifica evento',
