    'foto.etichetta.obiettivo': 'Obiettivo',
    'foto.etichetta.esposizione': 'Esposizione',
    'foto.etichetta.errore': 'Errore da evitare',
    'calendario.oggi': 'Oggi',

    // --- Il riquadro «Stanotte» della dashboard -------------------------
    'stanotte.mancaPosizione': 'Manca la tua posizione',
    'stanotte.mancaPosizioneTesto': 'Senza un punto sulla Terra non posso dirti a che ora fa buio, cosa sorge e cosa tramonta. Ci sono tre modi per darmelo — il GPS, la connessione o la tua città scelta in elenco — e almeno uno funziona sempre. Resta salvato solo su questo dispositivo.',
    'stanotte.buioAstronomico': 'Buio astronomico',
    'stanotte.nienteBuio': 'niente buio completo stanotte',
    'stanotte.tramontoAlba': 'Tramonto {tramonto} · alba {alba}',
    'stanotte.crepuscoloTuttaNotte': 'Il Sole non scende mai a \u221218°: crepuscolo per tutta la notte. Tramonto {tramonto}.',
    'stanotte.nonCalcolabile': 'non calcolabile',
    'stanotte.latitudiniAlte': 'Alle tue latitudini il Sole potrebbe non tramontare affatto.',
    'stanotte.lunaOrari': 'Sorge {sorge} · tramonta {tramonta}.',
    'stanotte.disturbo.alto': 'cielo molto schiarito: meglio Luna e pianeti che oggetti deboli',
    'stanotte.disturbo.medio': 'disturbo moderato per gli oggetti deboli',
    'stanotte.disturbo.basso': 'cielo scuro: ottimo per meteore e deep sky',
    'stanotte.datiNonDisponibili': 'dati non disponibili',
    'stanotte.senzaLibreriaOrbitale': 'Libreria orbitale non caricata: riapri l\'app quando c\'è rete, poi funzionerà anche offline.',
    'stazione.passaggio': 'Cielo di {quando}: {nome} è verso {dove}, a {alt}° di altezza. La mappa la insegue da sola — trascinala col dito per sganciarla.',
    'stazione.adesso': '{nome} adesso è verso {dove}, a {alt}° di altezza. La mappa la insegue da sola — trascinala col dito per sganciarla.',
    'stazione.sottoOrizzonte': '{nome} in questo momento è sotto l\'orizzonte, verso {dove} a {alt}°: la mappa ci punta lo stesso, sotto la linea del terreno.',
    'stazione.senzaDati': 'Sto scaricando i dati orbitali di {nome}: appena arrivano la mappa ci si punta da sola.',
    'eventoStazione.titolo': 'Passaggio visibile di {nome}',
    'eventoStazione.spiegazione': '{nome} passa illuminata dal Sole mentre da qui il cielo è buio: culmina a {altezza}° verso {direzione} e resta osservabile per circa {durata} min.',
    'eventoStazione.cosaPortare': 'Non serve alcuno strumento: si vede facilmente a occhio nudo.',
    'eventoStazione.doveVederlo': 'Compare alle {inizio} verso {direzioneInizio}, culmina alle {culmine} verso {direzioneCulmine} e sparisce alle {fine} verso {direzioneFine}.',
    'eventoStazione.comeVederlo': 'Esci qualche minuto prima e cerca una luce simile a una stella che scorre regolare, senza lampeggiare.',
    'eventoStazione.giudizio': 'Ben visibile: illuminata dal Sole, a {altezza}° verso {direzione}.',
    'faseLuna.nuova': 'Luna Nuova',
    'faseLuna.crescente': 'Luna crescente',
    'faseLuna.primoQuarto': 'Primo Quarto',
    'faseLuna.gibbosaCrescente': 'Gibbosa crescente',
    'faseLuna.piena': 'Luna Piena',
    'faseLuna.gibbosaCalante': 'Gibbosa calante',
    'faseLuna.ultimoQuarto': 'Ultimo Quarto',
    'faseLuna.calante': 'Luna calante',

    // --- Il blocco «Da qui» delle schede dell'agenda -------------------
    'locale.servePosizione': 'Con la tua posizione posso dirti se questo evento si vede da casa tua, a che ora e in che direzione.',
    'locale.sorgeTramonta': 'Sorge {sorge} · tramonta {tramonta}',
    'locale.buioAstronomico': 'Buio astronomico quella notte: {da} → {a}',
    'locale.osservabilita': 'Osservabilità {punti}/100',
    'locale.momentoConsigliato': 'Momento consigliato: {quando}',
    'locale.sottoMaRecupera': 'Al momento del picco è sotto l\'orizzonte da qui, ma nella stessa notte arriva a {gradi}° verso le {ora}.',
    'locale.nonVisibile': 'Non visibile da qui: nell\'istante dell\'evento l\'astro si trova sotto l\'orizzonte.',
    'locale.cieloAncoraChiaro': 'All\'ora esatta dell\'evento il cielo è ancora chiaro (Sole a {sole}°)',
    'locale.guardaloVersoLe': ': guardalo verso le {ora}, quando è alto {gradi}° verso {dove}.',
    'locale.cercaNelBuio': '. Cerca l\'astro nelle ore di buio più vicine.',
    'locale.bassaSullOrizzonte': 'Visibile ma bassa sull\'orizzonte ({gradi}°): serve una vista libera verso {dove}.',
    'locale.benVisibile': 'Ben visibile da qui: {gradi}° sopra l\'orizzonte, verso {dove}.',

    // --- I consigli di astrofotografia ---------------------------------
    'foto.base.treppiede': 'Un treppiede (anche piccolo) fa più differenza di qualsiasi obiettivo costoso.',
    'foto.base.telefono': 'Col telefono: modalità Pro o Notte, autoscatto di 3 secondi per non muoverlo, messa a fuoco manuale su ∞.',
    'foto.luna.titolo': 'Fotografare la Luna',
    'foto.luna.obiettivo': 'Il più lungo che hai: 200–300 mm su reflex, zoom ottico sul telefono.',
    'foto.luna.esposizione': 'Regola “lunare”: 1/125 s, f/8, ISO 100. La Luna è illuminata dal Sole, quindi va trattata come un soggetto diurno.',
    'foto.luna.errore': 'L\'errore classico è sovraesporre: se viene un disco bianco senza crateri, riduci di 2–3 stop.',
    'foto.eclissi.titolo': 'Fotografare l\'eclissi',
    'foto.eclissi.obiettivo': 'Teleobiettivo 200 mm o più. Per quella solare serve un filtro solare certificato davanti all\'obiettivo.',
    'foto.eclissi.esposizione': 'Eclissi lunare: ISO 800, f/5.6, 1/4 s durante la totalità (la Luna rossa è molto più scura). Eclissi solare parziale: come una foto diurna, ma solo con filtro.',
    'foto.eclissi.errore': 'Mai puntare il Sole senza filtro: bruci il sensore e, se guardi nel mirino, anche l\'occhio.',
    'foto.meteore.titolo': 'Fotografare le stelle cadenti',
    'foto.meteore.obiettivo': 'Grandangolo luminoso (14–24 mm, f/2.8 o più aperto): serve campo, non ingrandimento.',
    'foto.meteore.esposizione': 'ISO 1600–3200, f/2.8, pose da 15–20 s a raffica per ore. Regola del 500: secondi massimi = 500 ÷ lunghezza focale, oltre le stelle diventano trattini.',
    'foto.meteore.errore': 'Non si insegue la meteora: si punta la camera in una zona di cielo a ~40° dal radiante e si scatta in continuo.',
    'foto.pianeti.titolo': 'Fotografare pianeti e congiunzioni',
    'foto.pianeti.obiettivo': 'Per la congiunzione basta un 50–100 mm: bello è il paesaggio con i due astri vicini.',
    'foto.pianeti.esposizione': 'ISO 400–800, f/4, 1–2 s se sono ancora nel crepuscolo. I pianeti sono luminosi: meglio esporre poco.',
    'foto.pianeti.errore': 'Includi un albero o un profilo di case: una foto di due puntini nel nero non racconta nulla.',
    'foto.cielo.titolo': 'Fotografare il cielo',
    'foto.cielo.obiettivo': 'Grandangolo luminoso e messa a fuoco manuale su una stella brillante.',
