    'tel.cielo.6.nota': 'Via Lattea invisibile, alone luminoso all\'orizzonte.',
    'tel.cielo.8': 'Città',
    'tel.cielo.8.nota': 'Si vedono poche decine di stelle: pianeti e Luna restano ottimi.',

    // Com'è fatto davvero un oggetto all'oculare
    'tel.profondo.M31.aspetto': 'Un ovale lattiginoso grande come tre Lune in fila. Il nucleo è netto, le braccia no: quelle restano alle fotografie.',
    'tel.profondo.M42.aspetto': 'L\'unica nebulosa che mostra davvero una forma: due ali di gas grigio-verde attorno a quattro stelline in quadrato (il Trapezio).',
    'tel.profondo.M45.aspetto': 'Troppo grande per il telescopio: sta tutta solo nel cercatore o nel binocolo. Stelle azzurre, taglienti.',
    'tel.profondo.M44.aspetto': 'Una quarantina di stelle sparse, larghe. Anche qui l\'oculare più largo è quello giusto.',
    'tel.profondo.M13.aspetto': 'Una palla di luce granulosa: a 100× i bordi cominciano a scomporsi in singole stelle. È il colpo d\'occhio migliore del cielo estivo.',
    'tel.profondo.M8.aspetto': 'Una macchia grigia allungata tagliata da una fessura scura, con un ammasso di stelle appoggiato sopra.',
    'tel.profondo.M22.aspetto': 'Più largo e più risolto di M13, ma sta basso: la foschia dell\'orizzonte se ne mangia metà.',
    'tel.profondo.Doppio.aspetto': 'Due pugni di stelle nello stesso campo, a poca distanza. Serve l\'oculare più largo per averli tutti e due insieme.',
    'tel.profondo.M57.aspetto': 'Una ciambella grigia piccolissima ma inconfondibile. Regge bene l\'ingrandimento: qui il 4 mm ha senso.',
    'tel.profondo.M27.aspetto': 'Un torsolo di mela luminoso, grigio-verde. Fra le nebulose è la più facile dopo M42.',
    'tel.profondo.M51.aspetto': 'Due macchioline tonde vicine. Il ponte di materia che le unisce, nelle foto così evidente, all\'oculare non c\'è.',
    'tel.profondo.M81.aspetto': 'Ovale netto e luminoso; nello stesso campo M82, che invece è un fuso sottile. Due galassie in un colpo solo.',
    'tel.profondo.M15.aspetto': 'Palla compatta con il centro molto concentrato: sembra una cometa senza coda.',
    'tel.profondo.M3.aspetto': 'Globulare di prima qualità, quasi come M13: comincia a risolversi verso i 120×.',
    'tel.pianeta.Moon.aspetto': 'Lungo il terminatore (il confine fra luce e ombra) i crateri hanno ombre lunghe e sembrano in rilievo. È lì che si guarda, non sulla parte piena.',
    'tel.pianeta.Mercury.aspetto': 'Un dischetto minuscolo con una fase, come una Luna in miniatura. Sempre basso, sempre tremolante.',
    'tel.pianeta.Venus.aspetto': 'Abbagliante e completamente liscio: nessun dettaglio, solo la fase. Bellissima da falce, poco prima del tramonto.',
    'tel.pianeta.Mars.aspetto': 'Piccolo e arancione. Solo vicino alle opposizioni mostra la calotta polare bianca e qualche macchia scura.',
    'tel.pianeta.Jupiter.aspetto': 'Due bande scure attraversano il disco, e quattro puntini in fila cambiano posto ogni sera: sono le lune di Galileo.',
    'tel.pianeta.Saturn.aspetto': 'L\'anello si vede già a 50×, staccato dal disco verso i 120×. È l\'oggetto che convince chiunque guardi.',
    'tel.pianeta.Uranus.aspetto': 'Un dischetto verdino appena più grande di una stella: la soddisfazione sta nel riconoscerlo, non nel dettaglio.',
    'tel.pianeta.Neptune.aspetto': 'Indistinguibile da una stella se non per il colore bluastro. Serve la mappa per essere sicuri di averlo trovato.',

