    'did.retro.distanzaDalSole': 'Distanza dal Sole in cielo',
    'did.retro.luminosita': 'Luminosità',
    'did.retro.nota': 'Il cappio a destra è disegnato in coordinate eclittiche vere: la sua forma cambia a ogni passaggio perché dipende da quanto l\'orbita del pianeta è inclinata sulla nostra. I due dischi sono fuori scala — a scala vera la Terra sarebbe invisibile.',
    'did.retro.ponteCielo': 'Guardalo in cielo a questa data',
    'did.retro.ponteCieloTitolo': 'Porta il planetario alla data mostrata, puntato sul pianeta',
    'did.retro.fermo': 'fermo (stazionario)',
    'did.retro.retrogrado': 'retrogrado — va all\'indietro',
    'did.retro.diretto': 'diretto — va avanti',
    'did.retro.primiAlGiorno': '{n}′ al giorno',
    'did.retro.uaEMilioni': '{ua} UA · {km} milioni di km',
    'did.retro.gradiDalSole': '{n}° dal Sole',
    'did.retro.magnitudine': 'magnitudine {n}',
    'did.retro.opposizione': 'Opposizione: {data}',
    'did.retro.opposizioneCorto': 'opposizione',
