    'did.voy.prossimoIncontro': 'Prossimo incontro',
    'did.voy.notaPosizioni': 'Le posizioni dei quattro giganti sono quelle vere, calcolate anno per anno, <strong>z compresa</strong>: l\'allineamento del Grand Tour — che si ripresenta una volta ogni 176 anni — è quello che c\'era davvero. Le date degli incontri, le distanze di massimo avvicinamento e le due inclinazioni di fuga (35° sopra il piano per la 1, 48° sotto per la 2) sono esatte. La traiettoria fra un incontro e l\'altro è stilizzata — passa per i punti veri nei giorni veri, ma la curva che li unisce è disegnata — e i valori di velocità sono quelli indicativi ricostruiti dalle carte JPL.',
    'did.voy.nonAncoraPartita': 'non ancora partita',
