    'did.lancio.notaHohmann': 'Il conto è quello dell\'orbita di Hohmann, la più economica che ci sia: mezza ellisse tangente a tutt\'e due le orbite. Le sonde vere ne usano varianti più veloci e più care, e spesso ci aggiungono una fionda o due — ma la finestra resta, e resta larga poche settimane.',
    'did.lancio.ponteTred': 'Portami alla prossima finestra vera',
