    'did.lancio.mancatoDi': 'mancato di {milioni} milioni di km',
    'did.lancio.mancatoAvanti': 'Mancato: {nome} era {milioni} milioni di km più avanti',
    'did.lancio.mancatoIndietro': 'Mancato: {nome} era {milioni} milioni di km più indietro',
    'did.lancio.spiegaPrima': 'Per arrivare a {nome} la sonda deve percorrere <strong>mezza ellisse</strong> {ellisse}: ci mette <strong>{giorni} giorni</strong>, e questo numero non si può cambiare — lo fissa Keplero. Quindi {nome} al momento del lancio deve trovarsi <strong>{gradi}° {dove}</strong> della Terra, per essere al punto d\'arrivo quando ci arriva la sonda. Questa configurazione si ripete {ogni}: è la finestra di lancio, e fuori da lì non si parte.',
    'did.lancio.ellisseInterna': 'con l\'afelio sull\'orbita della Terra e il perielio su quella di {nome}',
    'did.lancio.ellisseEsterna': 'col perielio sull\'orbita della Terra e l\'afelio su quella di {nome}',
    'did.lancio.piuAvanti': 'più avanti',
    'did.lancio.piuIndietro': 'più indietro',
    'did.lancio.spiegaMancato': 'Partire {n} giorni {quando} non sposta l\'orbita della sonda — quella è sempre la stessa ellisse, e ci mette sempre {giorni} giorni. Sposta il pianeta: in quei giorni {nome} si è mosso di <strong>{gradi}°</strong> rispetto a dove doveva stare, che alla sua distanza fanno <strong>{milioni} milioni di chilometri</strong>. Con il propellente di bordo, una correzione così non si paga: si aspetta la finestra dopo.',
    'did.lancio.dopo': 'dopo',
    'did.lancio.prima': 'prima',
    'did.lancio.spiegaCentrato': 'Centrato. La sonda ha percorso <strong>{giorni} giorni</strong> di volo cieco — nessuna spinta, solo caduta libera attorno al Sole — e ha trovato {nome} esattamente dove doveva essere. È così che si arriva su un pianeta: non si insegue, si dà appuntamento.',
    'did.lancio.spiegaInVolo': 'La sonda è in caduta libera. Dopo la {manovra} iniziale di <strong>{dv1} km/s</strong> non accende più niente: {seguito}.',
    'did.lancio.frenata': 'frenata',
    'did.lancio.spinta': 'spinta',
    'did.lancio.scendeAlPerielio': 'scende verso il perielio andando sempre più forte (seconda legge di Keplero), e quando ci arriva le servirà un\'altra spinta di {dv2} km/s per frenare, se no risale',
    'did.lancio.saleAllAfelio': 'sale verso l\'afelio rallentando (seconda legge di Keplero), e quando ci arriva le servirà un\'altra spinta di {dv2} km/s per non ricadere indietro',
    'did.lancio.puntoDArrivo': 'punto d\'arrivo',

    // Banco 5 — gli allineamenti
    'did.allin.cerca': 'Cerca',
    'did.allin.vuoto': 'Scegli i pianeti e premi <strong>Cerca</strong>: l\'app scorre le posizioni vere giorno per giorno e tiene solo le configurazioni più strette.',
    'did.allin.nota': 'Un «allineamento» perfetto non esiste: le orbite sono inclinate l\'una sull\'altra, e la fila è sempre approssimata. Qui la misura è lo <strong>scarto</strong>: il settore angolare più stretto che contiene tutti i pianeti scelti. Sotto i dieci gradi si può già parlare di fila.',
    'did.allin.servonoDue': 'Servono almeno due pianeti.',
    'did.allin.ricercaInCorso': 'Ricerca in corso…',
    'did.allin.perGiorniEsaminati': '{perc}% dei giorni esaminati',
    'did.allin.vicinanza1': 'più vicini di una Luna piena: sembrano quasi una stella sola',
    'did.allin.vicinanza2': 'entro tre dischi di Luna: entrambi nello stesso campo del binocolo',
    'did.allin.vicinanza3': 'un dito a braccio teso li copre tutti e due',
    'did.allin.vicinanza4': 'due dita a braccio teso: una coppia che si nota subito',
    'did.allin.riassunto': 'Nei prossimi {anni} anni la fila più stretta di questi {n} pianeti attorno al Sole è di <strong>{gradi}°</strong>, il {data}. {giudizio}',
    'did.allin.giudizioMai': 'Cioè: non si allineano affatto, e non è un caso — con {n} pianeti che girano a velocità tutte diverse, trovarli nello stesso spicchio è praticamente impossibile. Togline qualcuno e guarda come cambia.',
    'did.allin.giudizioVentaglio': 'Un bel raggruppamento, ma non una fila: a occhio, dall\'esterno, si vedrebbe un ventaglio.',
    'did.allin.giudizioFila': 'Una fila vera e propria — con questi pianeti è un evento raro.',
    'did.allin.nessunaConfigurazione': 'Nessuna configurazione stretta da segnalare. Prova con un periodo più lungo, o con Venere e Giove: sono i due che si incontrano più spesso, e sono anche i due più luminosi del cielo.',
    'did.allin.marchioElio': 'fila dal Sole',
    'did.allin.marchioRaduno': 'raduno in cielo',
    'did.allin.marchioCongiunzione': 'congiunzione',
    'did.allin.testoElio': 'Tutti dalla stessa parte del Sole, dentro a un settore di {gradi}°: è la configurazione più stretta che questi pianeti raggiungono nel periodo cercato. È una posizione vera dello spazio, e si vede solo dall\'esterno — dalla Terra non ci si accorge di niente.',
    'did.allin.testoRaduno': 'Tutti e {n} dentro a {gradi}° di cielo: un raduno che si vede a occhio nudo, se il Sole non è di mezzo.',
    'did.allin.testoCoppia': '{primo} e {secondo} a <strong>{gradi}°</strong> l\'uno dall\'altro — {come}.',
    'did.allin.avvisoBasso': 'Attenzione: a {gradi}° dal Sole, quindi bassissima sull\'orizzonte e immersa nel crepuscolo. Difficile, ma non impossibile.',
    'did.allin.guardaloInCielo': 'Guardalo in cielo',

