    'did.aurL.talmenteBasso': 'talmente basso da essere spento dall\'aria',
    'did.aurL.tAddosso': 'Da <strong>{luogo}</strong> con Kp {kp} l\'ovale è praticamente addosso — {km} km — e le tende arrivano a {cima}° sopra l\'orizzonte, cioè quasi allo zenit. Da sotto l\'ovale l\'aurora non si guarda «verso {verso}»: si guarda in su, e la corona aurorale si apre a raggiera sopra la testa.',
    'did.aurL.tArchi': 'Da <strong>{luogo}</strong> con Kp {kp} l\'ovale è a {km} km: abbastanza vicino perché il verde stia sopra l\'orizzonte ({verde}°) e si vedano gli archi, non solo il bagliore. La cima della tenda arriva a {cima}° verso {verso}.',
