    'did.spa.nota': 'Le distanze vengono dalle parallassi di Hipparcos (database HYG). Per una decina di stelle molto lontane la parallasse non basta a dare un numero: quelle sono segnate con un punto interrogativo, e messe alla distanza mediana della loro figura. Le magnitudini nel terzo quadro sono ricalcolate dalla distanza vera: allontanandosi non cambia solo il disegno, cambia anche quali stelle si vedono ancora. Andando a stare su una stella della figura, quella lì sparisce dal cielo — è il Sole di quel posto — e le altre si riordinano da capo: il grigio tratteggiato è come stavano viste da qui.',
