    'did.tram.kmAria': '{km} km d\'aria contro gli 8,4 che basterebbero col Sole sulla testa: {x} volte.',
    'did.tram.soleSottoOrizzonte': 'Il Sole è sotto l\'orizzonte: la luce che resta ha attraversato tutto questo e oltre.',
    'did.tram.everest': 'Otto chilometri e mezzo è poco più dell\'Everest (8,8) e meno di un aereo di linea (11).',
    'did.tram.stessoMetro': 'Curvatura, spessore e cammino allo stesso metro — nessuna esagerazione.',
    'did.tram.rifrazione': 'rifrazione {n}′',
    'did.tram.dovEDavvero': 'dov\'è davvero il Sole',
    'did.tram.discoSchiacciato': 'Disco schiacciato del {pct}% · rifrazione {r}′ contro i 32′ del diametro',
    'did.tram.discoSotto': 'Il disco è sotto l\'orizzonte: resta il crepuscolo',
    'did.tram.campoInquadrato': 'Campo inquadrato: {gradi}° in altezza — il Sole è alla sua misura vera',
    'did.tram.tuttaLaLuce': 'tutta la luce (100%)',
