    'cost.cieloEquatoriale': 'cielo equatoriale',
    'cost.conDisegno': 'con disegno',
    'cost.maiVisibile': '<strong>Da qui non si vede mai.</strong> Alla tua latitudine ({lat}°) resta tutta sotto l\'orizzonte, a qualunque ora e in qualunque mese: non è questione di aspettare la notte giusta, è la curvatura della Terra. Il tasto qui sotto ti porta dove si vede.',
    'cost.circumpolare': '<strong>Da qui non tramonta mai:</strong> gira intorno al polo e resta sopra l\'orizzonte tutta la notte, tutto l\'anno. Al massimo arriva a {gradi}° di altezza.',
    'cost.altezzaMassima': 'Da qui arriva al massimo a <strong>{gradi}°</strong> sopra l\'orizzonte{nota}.',
    'cost.bassaNota': ' — bassa, serve un orizzonte libero da quella parte',
