    'ui.gradi-decimali-con-il-punto-sud-e-ovest-si': 'Gradi decimali, con il punto: sud e ovest si scrivono col meno (−). Su una mappa online basta tenere premuto sul punto per leggerle.',
    'ui.guarda': 'Guarda',
    'ui.guarda-il-cielo-da-qui': 'Guarda il cielo da qui',
