    'ui.mostra-gli-astri-anche-quando-si-trovano': 'Mostra gli astri anche quando si trovano dietro il profilo di colline e montagne. Spento, il terreno li nasconde come avviene nella realtà',
    'ui.mostra-i-pulsanti-e-sulla-mappa': 'Mostra i pulsanti + e − sulla mappa',
    'ui.mostra-il-colore-del-cielo-la-foschia-e-gli': 'Mostra il colore del cielo, la foschia e gli aloni. Spegnendola si spengono anche le nuvole',
    'ui.mostra-in-cielo': 'Mostra in cielo',
    'ui.mostra-tutti-i-dati': 'Mostra tutti i dati',
    'ui.nasconde-tutte-le-informazioni-e-i-comandi': 'Nasconde tutte le informazioni e i comandi in sovrimpressione; resta solo il pulsante di registrazione. Tocca il cielo per farli ricomparire',
    'ui.nascondi': 'Nascondi',
    'ui.nascondi-automaticamente-la-carta-del': 'Nascondi automaticamente la carta del tragitto dopo questo tempo.',
    'ui.nascondi-la-linea-del-giorno-e-della-notte': 'Nascondi la linea del giorno e della notte',
    'ui.nel-planetario-puoi-vedere-paesi-acqua': 'Nel planetario puoi vedere paesi, acqua, montagne e aerei in tempo reale. Fin dove cercarli lo decidi qui, sulla carta: al centro c\'è dove guardi il cielo, e i quattro cerchi sono i raggi di ricerca. Trascina il bordo di un cerchio, oppure tocca il punto fin dove vuoi arrivare; puoi anche allargare la mappa a tutto schermo.',
    'ui.nel-raggio': 'nel raggio',
    'ui.nessun-astro-con-questo-nome': 'Nessun astro o costellazione con questo nome.',
