    'ui.posizione': 'Posizione',
    'ui.posizione-attuale': 'Posizione attuale',
    'ui.posizioni-ads-b-entro-il-raggio-scelto-50-km': 'Posizioni ADS-B entro il raggio scelto (50 km di serie; si cambia nelle Impostazioni). Il colore dice quanto è vicino; la linea tratteggiata è la rotta dei 5 minuti successivi. Spostando l\'orologio, aereo e rotta diventano stime coerenti con l\'istante mostrato.',
    'ui.precisa-al-metro': 'precisa al metro',
    'ui.prendi-quello-che-hai-copiato': 'Prendi quello che hai copiato',
    'ui.prepariamo-il-planetario': 'Prepariamo il planetario',
    'ui.programma-facoltativo': 'Programma (facoltativo)',
    'ui.prossimi-appuntamenti': 'Prossimi appuntamenti',
    'ui.pulisci': 'Pulisci',
    'ui.punta-il-mirino-su-un-astro-che-vedi-davvero': 'Punta il mirino su un astro che vedi davvero (la Luna, il Sole, un pianeta, una stella luminosa) e tocca qui: la bussola si corregge sul cielo vero',
    'ui.puoi-scegliere-una-cartella-gia-esistente-e': 'Puoi scegliere una cartella già esistente e caricare subito i video che contiene, oppure crearne una nuova.',
    'ui.quando': 'Quando',
    'ui.quante-stelle-si-vedono-non-dipende-dal': 'Quante stelle si vedono non dipende dal cielo ma da dove lo guardi. Scegli quello che assomiglia di più al tuo: comanda il planetario (quante stelle disegna), la scelta dei bersagli di stanotte e il conto del contrasto al telescopio.',
    'ui.quanti-minuti-di-eclissi-scorrono-in-un': 'Quanti minuti di eclissi scorrono in un secondo di filmato',
    'ui.quanto-manca-alla-forma-vera-del-terreno': 'Quanto manca alla forma vera del terreno',
    'ui.qui-la-luna-resta-su-dal-primo-all-ultimo': 'Qui la Luna resta su dal primo all\'ultimo contatto. La zona è più stretta perché intanto la Terra gira.',
    'ui.raggio-di-ricerca': 'Raggio di ricerca',
    'ui.rapidissima': 'rapidissima',
