    'ui.sei-banchi-di-prova-con-dentro-le-posizioni': 'Sei banchi di prova con dentro le posizioni vere dei pianeti, per capire le sei cose che stanno\n          dietro a tutto il resto dell\'app: perché i pianeti a volte tornano indietro, quali sono le tre\n          regole che comandano ogni orbita, come si guadagna velocità passando vicino a un pianeta, perché\n          per Marte si parte solo ogni ventisei mesi, quando i pianeti si mettono davvero in fila e come\n          fa il Sole ad accendere un\'aurora dall\'altra parte del pianeta.\n          Ogni banco finisce con i tasti che portano la stessa cosa nel planetario e nel Sistema Solare in 3D.',
