    'ui.tocca-un-punto-qualunque-del-mappamondo-per': 'Tocca un punto qualunque del mappamondo per sceglierlo, oppure toccalo due volte per andarci subito: il planetario disegnerà il cielo di lì. La posizione dell\'app non si tocca.',
